
INSERT INTO public.faq_kb (language, question, answer, tags, trigger_phrases, is_active, priority) VALUES
-- FR: Product condition
('fr', 'Les produits sont-ils neufs ?', 'Oui, tous nos produits sont 100% neufs, jamais utilisés. Ils arrivent dans leur emballage d''origine scellé (carton/boîte de la marque).', ARRAY['products','condition'], ARRAY['neuf','neufs','neuve','occasion','seconde main','usagé','carton','emballage','boite','boîte','scellé','scelle','original','authentique','vrai','copie','contrefaçon','contrefacon','genuine','brand new'], true, 90),
('fr', 'C''est en carton ?', 'Oui ✅ tous nos produits sont neufs et arrivent dans leur carton d''origine scellé, directement de la marque (Apple, Samsung, etc.).', ARRAY['products','packaging'], ARRAY['carton','emballage','boite','boîte','scellé','scelle','neuf','sealed','box'], true, 95),
('fr', 'Avez-vous une garantie ?', 'Oui, tous les produits bénéficient de la garantie officielle du fabricant (généralement 1 an). Si le produit arrive défectueux, nous vous remplaçons ou remboursons sous 7 jours.', ARRAY['warranty','returns'], ARRAY['garantie','warranty','défectueux','defectueux','cassé','casse','panne','remplacement'], true, 80),
('fr', 'Les prix sont-ils négociables ?', 'Nos prix sont déjà tout compris (prix + douane + transport + livraison) et au plus bas. Mais vous pouvez payer en 2 fois: **30% maintenant + 70% à la livraison** 💪', ARRAY['pricing','negotiation'], ARRAY['réduction','reduction','remise','rabais','négocier','negocier','moins cher','discount','promo','prix final'], true, 95),
('fr', 'Pourquoi le délai de livraison est si long ?', 'Nos produits viennent des USA/Dubaï/Chine et passent par la douane RDC, ce qui prend 2-4 semaines. C''est le délai standard pour de l''import authentique. ✨ Bonne nouvelle: vous ne payez que **30% maintenant** et le reste à la livraison.', ARRAY['delivery','complaint'], ARRAY['trop long','long','lent','lente','attendre','attente','patience','délai trop','delai trop'], true, 90),
('fr', 'Comment fonctionne le paiement 30/70 ?', 'Vous payez **30% à la commande** pour démarrer l''importation, puis **70% à la livraison** quand vous recevez le colis chez vous. Pas de frais cachés, pas de surprise.', ARRAY['payment','plan'], ARRAY['30/70','30 70','acompte','plusieurs fois','paiement échelonné','echelonne','plan paiement'], true, 95),
('fr', 'Puis-je modifier mon adresse de livraison ?', 'Oui, contactez le support immédiatement avec votre numéro de commande. Tant que la commande n''est pas expédiée, nous pouvons modifier l''adresse.', ARRAY['orders','modify'], ARRAY['adresse','changer adresse','modifier livraison','wrong address'], true, 70),
('fr', 'Dois-je payer la douane ?', 'Non ✅ Nos prix sont **tout compris** : produit + douane + transport + livraison à votre porte. Vous ne payez rien d''autre.', ARRAY['customs','pricing'], ARRAY['douane','customs','taxes','frais cachés','frais caches','tva','dédouanement','dedouanement'], true, 90),
('fr', 'Combien de temps pour un remboursement ?', 'Les remboursements sont traités sous 5-10 jours ouvrables après validation. L''argent retourne sur le même moyen de paiement utilisé.', ARRAY['refund','timeline'], ARRAY['remboursement','combien temps remboursement','quand remboursé','rembourse'], true, 75),
('fr', 'Livrez-vous en dehors de Kinshasa ?', 'Oui, nous livrons dans toute la RDC (Lubumbashi, Goma, Bukavu, Mbuji-Mayi, Kisangani, etc.) ainsi qu''au Congo Brazzaville. Les frais et délais varient selon la ville.', ARRAY['delivery','coverage'], ARRAY['lubumbashi','goma','bukavu','province','brazzaville','en dehors','autre ville'], true, 80),
('fr', 'Comment puis-je vous faire confiance ?', 'AfriShop est une société enregistrée en RDC avec un bureau physique à Kinshasa, plus de 1000 clients satisfaits, et un système de paiement sécurisé. Vous ne payez que 30% au départ — vous ne risquez quasi rien.', ARRAY['trust','legitimacy'], ARRAY['arnaque','scam','confiance','vrai site','réel','reel','fiable','sérieux','serieux'], true, 85),
('fr', 'Mon paiement ne passe pas, que faire ?', 'Vérifiez votre solde et réessayez. Si le problème persiste, essayez un autre moyen (Mobile Money / carte bancaire). Le support peut aussi vous envoyer un lien de paiement direct.', ARRAY['payment','failed'], ARRAY['paiement échoué','echoue','ne passe pas','erreur paiement','payment failed','bloqué'], true, 80),
('fr', 'Acceptez-vous le paiement à la livraison ?', 'Oui partiellement: **30% à la commande + 70% à la livraison** (paiement total à la livraison non disponible car nous devons d''abord acheter et importer le produit pour vous).', ARRAY['payment','cod'], ARRAY['cash livraison','paiement livraison','cod','cash on delivery'], true, 85),
('fr', 'Comment savoir si un produit est disponible ?', 'Tous les produits affichés sur AfriShop sont disponibles. Si un produit devient indisponible après votre commande, nous vous remboursons intégralement sous 48h.', ARRAY['stock','availability'], ARRAY['disponible','stock','en stock','rupture','indisponible'], true, 70),
('fr', 'Puis-je commander un produit qui n''est pas sur le site ?', 'Oui ✅ Collez le lien (Amazon, eBay, Shopify) dans la barre "Coller un lien" et nous calculerons le prix tout compris automatiquement.', ARRAY['custom','paste'], ARRAY['lien externe','pas sur site','autre produit','spécifique','specifique','coller lien'], true, 80),

-- EN equivalents
('en', 'Are products brand new?', 'Yes, all our products are 100% brand new, never used. They arrive in their original sealed packaging from the manufacturer (Apple, Samsung, etc.).', ARRAY['products','condition'], ARRAY['new','brand new','used','second hand','sealed','box','original','authentic','genuine','fake'], true, 90),
('en', 'Is it in the original box?', 'Yes ✅ all our products are brand new and arrive in their original sealed box, directly from the manufacturer.', ARRAY['products','packaging'], ARRAY['box','packaging','sealed','original box','new'], true, 95),
('en', 'Do you offer a warranty?', 'Yes, all products come with the official manufacturer warranty (usually 1 year). If a product arrives defective, we replace or refund within 7 days.', ARRAY['warranty'], ARRAY['warranty','defective','broken','replacement'], true, 80),
('en', 'Are prices negotiable?', 'Our prices are already all-inclusive (product + customs + shipping + delivery) and at our lowest. But you can split into 2 payments: **30% now + 70% on delivery** 💪', ARRAY['pricing'], ARRAY['discount','negotiate','cheaper','promo','reduce price','final price'], true, 95),
('en', 'Why is delivery so long?', 'Our products come from USA/Dubai/China and clear DRC customs, which takes 2-4 weeks. That''s the standard for authentic imports. ✨ Good news: you only pay **30% now** and the rest on delivery.', ARRAY['delivery','complaint'], ARRAY['too long','slow','wait','long delivery','take forever'], true, 90),
('en', 'How does the 30/70 payment work?', 'You pay **30% at order** to start the import, then **70% on delivery** when the package arrives at your door. No hidden fees, no surprises.', ARRAY['payment','plan'], ARRAY['30/70','deposit','split payment','installment','payment plan'], true, 95),
('en', 'Can I change my delivery address?', 'Yes, contact support immediately with your order number. As long as the order hasn''t shipped, we can update the address.', ARRAY['orders'], ARRAY['change address','wrong address','update address'], true, 70),
('en', 'Do I have to pay customs?', 'No ✅ Our prices are **all-inclusive**: product + customs + shipping + delivery to your door. You pay nothing extra.', ARRAY['customs','pricing'], ARRAY['customs','duty','tax','hidden fees','vat'], true, 90),
('en', 'How long for a refund?', 'Refunds are processed in 5-10 business days after approval. Money returns to the same payment method you used.', ARRAY['refund'], ARRAY['refund time','when refund','how long refund'], true, 75),
('en', 'Do you deliver outside Kinshasa?', 'Yes, we deliver across DRC (Lubumbashi, Goma, Bukavu, Mbuji-Mayi, Kisangani) and to Congo Brazzaville. Fees and timing vary by city.', ARRAY['delivery','coverage'], ARRAY['lubumbashi','goma','outside kinshasa','province','brazzaville'], true, 80),
('en', 'How can I trust you?', 'AfriShop is a registered DRC company with a physical Kinshasa office, 1000+ happy customers, and secure payments. You only pay 30% upfront — almost no risk.', ARRAY['trust'], ARRAY['scam','trust','legit','real','reliable'], true, 85),
('en', 'My payment failed, what do I do?', 'Check your balance and try again. If it persists, try another method (Mobile Money / bank card). Support can also send you a direct payment link.', ARRAY['payment'], ARRAY['payment failed','error','blocked','declined'], true, 80),
('en', 'Do you accept cash on delivery?', 'Partial yes: **30% at order + 70% on delivery**. Full COD isn''t possible because we must purchase and import the product for you first.', ARRAY['payment','cod'], ARRAY['cod','cash on delivery','pay on delivery'], true, 85),
('en', 'Can I order a product not on the site?', 'Yes ✅ Paste the link (Amazon, eBay, Shopify) into the "Paste a link" bar and we''ll calculate the all-inclusive price automatically.', ARRAY['custom','paste'], ARRAY['not on site','custom product','paste link','specific product'], true, 80);
